#[test]
fn a_recreated_run_is_a_different_identity() {
    // The forge#47 workload: purge `r`, create a new `r`, and the second must
    // not inherit the first's verdict.
    //
    // Scoped honestly. On a platform reporting birth time this is guaranteed;
    // where it does not, the identity is `dev`+`ino` and a recreated run CAN
    // in principle collide — which is why `RunIdentity::of` warns once on such
    // a host rather than pretending otherwise. This test asserts what holds
    // here; it is not a claim that inode reuse is impossible.
    let tmp = make_root("identity-recreate");
    let dir = make_run(tmp.path(), "r", b"# Spec");
    let before = RunIdentity::of(&dir).expect("before");

    fs::remove_dir_all(&dir).unwrap();
    let dir = make_run(tmp.path(), "r", b"# A different run");
    let after = RunIdentity::of(&dir).expect("after");

    assert_ne!(before, after, "a recreated run must not read as the same run");
}

